const webhook = $('Webhook').first()?.json ?? {};
let body = webhook.body ?? webhook;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch {
    return [{ json: { ok: false, valid: false, error: 'invalid_json', http_status: 400 } }];
  }
}
const itemId = typeof body.item_id === 'string' ? body.item_id.trim() : '';
const action = typeof body.action === 'string' ? body.action.trim() : '';
const actorId = typeof body.actor_id === 'string' ? body.actor_id.trim() : '';
const itemIdPattern = /^[A-Za-z0-9_-]{6,80}$/;
const actorIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const actions = new Set(['interest', 'contact_attempt', 'favorite_add', 'favorite_remove']);
const favoriteAction = action === 'favorite_add' || action === 'favorite_remove';
if (!itemIdPattern.test(itemId)) return [{ json: { ok: false, valid: false, error: 'item_id_invalid', http_status: 400 } }];
if (!actions.has(action)) return [{ json: { ok: false, valid: false, error: 'action_invalid', http_status: 400 } }];
if (favoriteAction && !actorIdPattern.test(actorId)) return [{ json: { ok: false, valid: false, error: 'actor_id_invalid', http_status: 400 } }];
const found = $input.all().map(({ json }) => ({ json, fields: json.fields ?? json })).find(({ fields }) => String(fields.public_id ?? fields['item-id'] ?? '') === itemId);
if (!found) return [{ json: { ok: false, valid: false, error: 'item_not_found', http_status: 404 } }];
const fields = found.fields;
const status = String(fields.status ?? 'hidden').toLowerCase();
if (!['available', 'reserved', 'completed', 'expired'].includes(status)) return [{ json: { ok: false, valid: false, error: 'item_not_found', http_status: 404 } }];
const rowId = fields.Id ?? found.json.Id ?? found.json.id ?? null;
if (rowId === null || rowId === undefined || rowId === '') return [{ json: { ok: false, valid: false, error: 'nocodb_row_id_missing', http_status: 500 } }];

if (favoriteAction) {
  const now = Date.now();
  const headers = webhook.headers ?? {};
  const forwardedIp = String(headers['x-forwarded-for'] ?? headers['x-real-ip'] ?? '').split(',')[0].trim();
  const rateState = $getWorkflowStaticData('global');
  const buckets = rateState.favoriteRateBuckets && typeof rateState.favoriteRateBuckets === 'object'
    ? rateState.favoriteRateBuckets
    : {};
  const windowStart = now - 10 * 60 * 1000;
  for (const [key, timestamps] of Object.entries(buckets)) {
    const active = Array.isArray(timestamps) ? timestamps.filter((timestamp) => Number(timestamp) >= windowStart) : [];
    if (active.length) buckets[key] = active;
    else delete buckets[key];
  }
  const rateKeys = [{ key: `actor:${actorId}`, limit: 20 }];
  if (forwardedIp) rateKeys.push({ key: `ip:${forwardedIp}`, limit: 120 });
  for (const { key, limit } of rateKeys) {
    if ((buckets[key] ?? []).length >= limit) {
      rateState.favoriteRateBuckets = buckets;
      return [{ json: { ok: false, valid: false, error: 'rate_limited', http_status: 429 } }];
    }
  }
  for (const { key } of rateKeys) {
    buckets[key] = [...(buckets[key] ?? []), now];
  }
  rateState.favoriteRateBuckets = buckets;
}

const interestCount = Math.max(0, Number(fields.interest_count ?? 0));
const contactAttemptCount = Math.max(0, Number(fields.contact_attempt_count ?? 0));
const favoriteCount = Math.max(0, Number(fields.favorite_count ?? 0));
const nextInterestCount = action === 'interest' ? interestCount + 1 : interestCount;
const nextContactAttemptCount = action === 'contact_attempt' ? contactAttemptCount + 1 : contactAttemptCount;
const favoriteDelta = action === 'favorite_add' ? 1 : action === 'favorite_remove' ? -1 : 0;
const nextFavoriteCount = Math.max(0, favoriteCount + favoriteDelta);
const count = action === 'interest'
  ? nextInterestCount
  : action === 'contact_attempt'
    ? nextContactAttemptCount
    : nextFavoriteCount;
return [{ json: {
  ok: true,
  valid: true,
  Id: rowId,
  item_id: itemId,
  action,
  count,
  interest_count: nextInterestCount,
  contact_attempt_count: nextContactAttemptCount,
  favorite_count: nextFavoriteCount,
  http_status: 200,
} }];
